                "    float shadow0 = 0.0;").encode()
VISIT_REPLACEMENT = ("        return SampleFilteredShadow(shadowPos, offset, subsurface);\r\n"
                     "    // Entered the real weighted path after every native fallback guard.\r\n"
                     "    shaderlodBslReceiverVisitedWeight = w;\r\n"
                     "    float shadow0 = 0.0;").encode()
OUTPUT_ANCHOR = b"    /* DRAWBUFFERS:0 */\r\n    gl_FragData[0] = albedo;"
OUTPUT_CUE = """    #ifdef SHADERLOD_BSL_RECEIVER_ACTIVE
    // Coverage witness after native lighting/encoding, before original MRT writes.
    // Existing postprocessing can mix colors. NEVER time this diagnostic:
    // the compiler may eliminate lighting/fetches unused by the final color.
    if (mat == 0.0 && albedo.a >= 0.999) {
        vec3 shaderlodBslReceiverCue = vec3(1.0, 0.0, 1.0); // Invalid marker.
        if (shaderlodBslReceiverVisitedWeight == -1.0) {
            shaderlodBslReceiverCue = vec3(0.0, 0.0, 1.0); // Native/unvisited.
        } else if (shaderlodBslReceiverVisitedWeight > 0.0 && shaderlodBslReceiverVisitedWeight < 1.0) {
            shaderlodBslReceiverCue = vec3(1.0, 1.0, 0.0); // Weighted transition.
        } else if (shaderlodBslReceiverVisitedWeight == 1.0) {
            shaderlodBslReceiverCue = vec3(0.0, 1.0, 0.0); // Weighted plateau.
        }
        albedo.rgb = shaderlodBslReceiverCue;
    }
    #endif

""".replace("\n", "\r\n").encode()


def sha256(data):
    return hashlib.sha256(data).hexdigest()


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":")).encode()


def read_archive(path):
    with zipfile.ZipFile(path) as archive:
        names = archive.namelist()
        if len(names) != len(set(names)) or any(
            PurePosixPath(n).is_absolute() or ".." in PurePosixPath(n).parts or
            "\\" in n or "\x00" in n for n in names
        ):
            raise ValueError("Unsafe or duplicate member")
        return {n: archive.read(n) for n in names if not n.endswith("/")}


def replace_once(source, before, after):
    if source.count(before) != 1:
        raise ValueError("Missing or ambiguous exact cue anchor")
    return source.replace(before, after, 1)


def apply(files, manifest):
    if manifest.get("id") != "bsl-receiver-coverage-r1" or not manifest.get("never_time"):
        raise ValueError("Not the reviewed coverage-only manifest")
    if set(files) != set(manifest["candidate_member_sha256"]):
        raise ValueError("Candidate member inventory changed")
    for name, digest in manifest["candidate_member_sha256"].items():
        if sha256(files[name]) != digest:
            raise ValueError("Pinned active candidate member changed: " + name)
    result = dict(files)
    result[TERRAIN] = replace_once(files[TERRAIN], DECLARATION_ANCHOR, DECLARATION_ANCHOR + DECLARATION)
    result[SHADOWS] = replace_once(files[SHADOWS], VISIT_ANCHOR, VISIT_REPLACEMENT)
    result[TERRAIN] = replace_once(result[TERRAIN], OUTPUT_ANCHOR, OUTPUT_CUE + OUTPUT_ANCHOR)
    for name in (TERRAIN, SHADOWS):
        if sha256(result[name]) != manifest["cue_member_sha256"][name]:
            raise ValueError("Cue source differs from reviewed patch")
    return result


def validate_inputs(base, options, iris, capture, manifest):
    for path, key in ((base, "candidate_archive_sha256"), (options, "candidate_sidecar_sha256"),
                      (iris, "iris_sha256"), (capture, "candidate_capture_sha256")):
        if sha256(Path(path).read_bytes()) != manifest[key]:
            raise ValueError("Unqualified pinned input: " + key)
    evidence = json.loads(Path(capture).read_bytes())
    options_map = evidence["loadedIrisOptions"]
    if len(options_map) != 387 or sha256(canonical(options_map)) != manifest["loaded_options_map_sha256"]:
        raise ValueError("Incomplete or changed actual active option map")
    if (evidence["selectedArchiveSha256"] != manifest["candidate_archive_sha256"] or
        evidence["irisFallback"] or not evidence["shaderPackInUse"] or
        evidence["pendingIrisOptionQueue"] or evidence["dhPresent"] or
        evidence["dimension"] != "minecraft:overworld" or
        (evidence["framebufferWidth"], evidence["framebufferHeight"]) != (1920, 1200)):
        raise ValueError("Unqualified prior active context")
    return evidence


def build(base=BASE, options=OPTIONS, iris=IRIS, capture=CAPTURE, output=None):
    raw_manifest = MANIFEST.read_bytes()
    if sha256(raw_manifest) != MANIFEST_SHA256:
        raise ValueError("Unreviewed coverage manifest")
    manifest = json.loads(raw_manifest)
    output = Path(output).resolve()
    sidecar, record = Path(str(output) + ".txt"), output.with_suffix(".json")
    if (output.suffix != ".zip" or not output.is_relative_to(OUTPUT_ROOT.resolve()) or
        any(p.exists() for p in (output, sidecar, record))):
        raise ValueError("Use fresh coverage ZIP/sidecars under ignored BSL coverage directory")
    validate_inputs(base, options, iris, capture, manifest)
    original = read_archive(base)
    files = apply(original, manifest)
    modified = sorted(n for n in original if files[n] != original[n])
    if modified != sorted((TERRAIN, SHADOWS)) or set(files) != set(original):
        raise ValueError("Only terrain output/marker and receiver entry may change")
    output.parent.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(output, "x", compression=zipfile.ZIP_DEFLATED) as archive:
        for name, data in sorted(files.items()):
            entry = zipfile.ZipInfo(name, (1980, 1, 1, 0, 0, 0))
            entry.compress_type = zipfile.ZIP_DEFLATED
            entry.external_attr = 0o100644 << 16
            archive.writestr(entry, data)
    with sidecar.open("xb") as f:
        f.write(Path(options).read_bytes())
    result = {
        "id": manifest["id"], "kind": "private-semantic-weighted-path-coverage-only", "never_time": True,
        "output": str(output), "archive_sha256": sha256(output.read_bytes()),
        "sidecar_sha256": sha256(sidecar.read_bytes()), "candidate_archive_sha256": manifest["candidate_archive_sha256"],
        "builder_sha256": sha256(Path(__file__).read_bytes()), "manifest_sha256": sha256(raw_manifest),
        "candidate_capture_sha256": manifest["candidate_capture_sha256"],
        "modified_members": modified, "cue_member_sha256": manifest["cue_member_sha256"],
        "unchanged_helper_sha256": sha256(files[HELPER]), "unchanged_properties_sha256": sha256(files["shaders/shaders.properties"]),
        "legend": manifest["legend"], "native_loaded_options_preserved": 384, "existing_private_options_preserved": 3,
        "runtime_obligations": manifest["runtime_obligations"],
        "driver_compiled": False, "coverage_observed": False, "physical_sample_counts_proved": False,
        "quality_acceptance": False, "performance_acceptance": False,
    }
    record.write_text(json.dumps(result, indent=2) + "\n")
    return result


def marker_color(marker):
    """Diagnostic legend reference; does not execute the GPU receiver."""
    if marker == -1:
        return "blue"
    if 0 < marker < 1:
        return "yellow"
    if marker == 1:
        return "green"
    return "magenta"


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--base", type=Path, default=BASE)
    parser.add_argument("--options", type=Path, default=OPTIONS)
    parser.add_argument("--iris", type=Path, default=IRIS)
    parser.add_argument("--capture", type=Path, default=CAPTURE)
    parser.add_argument("--output", type=Path, required=True)
    print(json.dumps(build(**vars(parser.parse_args())), indent=2))

